// Original repository-authored Python lessons. Expected output is tested in Python.
const example = (title, code, output, explanation) => ({ title, code, output, explanation });
const unit = (order, slug, title, explanation, rule, examples, task, hint) => ({ order, slug, title, explanation, rule, examples, task, hint });
export const pythonCoreUnits = [
  unit(2, 'types-and-explicit-conversion', 'Python Types and Explicit Conversion',
    'A type describes the kind of value an operation receives, not how its output happens to look. The integer 12 and the string "12" print similar characters, but adding two integers calculates a sum while adding two strings joins text. Start by identifying literal syntax, then inspect type(value) when you need evidence. Do not fix every error by converting everything to a string: decide whether the next operation needs text or a number.\n\nConversion is an explicit request to construct a value of another type. int("12") parses suitable integer text; str(12) constructs text; float("2.5") parses a decimal representation. Conversion can fail. int("twelve") raises ValueError because those characters are not integer syntax. int(2.9) truncates towards zero; it does not round to the nearest integer. Keep those operations distinct.\n\nFor a study-duration calculation, a numeric total should stay numeric until it is formatted for display. Store converted inputs under clear names rather than repeatedly converting the same text inside a long expression. This makes the point where validation belongs easier to find. Floating-point values also have finite precision, so printed decimal examples are not a promise of exact decimal arithmetic for money.',
    'Convert intentionally before an operation that requires a different kind of value.', [
      example('Inspect the type', 'value = "12"\nprint(type(value).__name__)\nprint(type(12).__name__)', 'str\nint', 'The first literal has quotation marks and produces a string. The second is an integer. __name__ gives the type name without the class wrapper that type itself displays. The printed digits alone would not reveal this distinction.'),
      example('Calculate after parsing', 'days_text = "5"\ndays = int(days_text)\nprint(days * 30)\nprint(days_text * 2)', '150\n55', 'Multiplying the parsed integer performs arithmetic. Multiplying the original string by an integer repeats the text. The original variable is not changed by constructing another value with int.'),
      example('Format only at the boundary', 'minutes = 150\nmessage = "Minutes: " + str(minutes)\nprint(message)\nprint(int(2.9))', 'Minutes: 150\n2', 'The total becomes text only for concatenation. The last line demonstrates truncation, which differs from rounding. Use the operation whose documented behaviour matches the problem.'),
    ], 'Start with days_text = "7" and minutes_text = "25". Parse both, calculate a numeric total, then print a labelled message. Also print the type name of the total. Explain why concatenating the original strings is not the calculation.', 'Parse the two strings separately before multiplying. Keep the total numeric until you create the message.'),
  unit(3, 'strings-indexing-and-slicing', 'Python Strings, Indexing and Slicing',
    'A string is an immutable sequence of Unicode code points. Indexing chooses one position, beginning at zero. Negative indices count back from the end, so -1 selects the last character of a nonempty string. Immutability means assigning text[0] = "X" does not edit a character in place. Construct a new string when you want changed text.\n\nA slice describes a range using start:stop, where stop is excluded. Leaving start empty begins at the start; leaving stop empty continues to the end. Slicing is forgiving when a boundary extends beyond the string, but indexing a missing position raises IndexError. These are different operations, not inconsistent handling of the same request.\n\nMethods such as strip and lower return new strings. Assign their result when you need to keep it. strip removes leading and trailing whitespace, not every space inside a sentence. Work through a short concrete example before combining several methods. A visible character can contain multiple Unicode code points, so advanced text editing needs more care than assuming every index corresponds to one user-perceived character.',
    'A slice excludes its stop position and returns a new string.', [
      example('Read positions', 'word = "Python"\nprint(word[0])\nprint(word[-1])\nprint(len(word))', 'P\nn\n6', 'P occupies index zero and n is the last character. len reports the sequence length. These ASCII characters each occupy one code point, making the index model easy to inspect.'),
      example('Take a slice', 'word = "Python"\nprint(word[1:4])\nprint(word[:2])\nprint(word[4:])', 'yth\nPy\non', 'The first slice includes indices one, two and three, but not four. The omitted bounds in the next two slices mean start of string and end of string respectively. The original word remains unchanged.'),
      example('Keep a method result', 'label = "  Study Time  "\nclean = label.strip().lower()\nprint(clean)\nprint(label.startswith("  "))', 'study time\nTrue', 'The cleaned value is a new string. The original label still starts with spaces. lower changes letter case; strip removes only the surrounding whitespace in this example.'),
    ], 'Use the string "  Python Practice  ". Save a cleaned version, print its first six characters and its last character, and verify that the original still contains its surrounding spaces. Explain the excluded stop index.', 'Store strip() in a new name. A six-character prefix uses [:6], not [:5].'),
  unit(4, 'operators-and-comparisons', 'Python Operators and Comparisons',
    'An operator describes an operation on operands. Arithmetic operators calculate values; comparison operators produce booleans. Assignment with = binds a name, while == compares values. Read those symbols deliberately rather than treating every equals sign as a question. Python uses ** for exponentiation; ^ is a bitwise operator, not a power symbol.\n\nFor integer operands, // computes floor division and % computes the corresponding remainder. Floor division moves towards negative infinity, which matters for negative numbers. The examples begin with positive counts so you can check the quotient and remainder against a concrete grouping problem. Parentheses make grouping explicit when an expression contains several operations.\n\nBoolean operators and, or and not combine truth tests. and and or short-circuit and actually return an operand, so avoid assuming every use constructs a bool. When you want a boolean condition, use clear comparison expressions on each side. Write a range check as 0 <= score <= 100 rather than accidentally checking only one boundary. Prefer a readable condition over a compressed expression that nobody can confidently trace.',
    'Assignment binds a name; comparison evaluates a relationship between values.', [
      example('Group arithmetic explicitly', 'print(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(2 ** 3)', '14\n20\n8', 'Multiplication happens before addition in the first expression. Parentheses change the grouping in the second. The third expression calculates a power, using two asterisks.'),
      example('Count complete groups', 'minutes = 95\nprint(minutes // 30)\nprint(minutes % 30)', '3\n5', 'Ninety-five minutes contains three complete thirty-minute blocks and five remaining minutes. This positive example provides a concrete interpretation of quotient and remainder.'),
      example('Compare a score', 'score = 80\nprint(score >= 80)\nprint(0 <= score <= 100)\nprint(score == 100)', 'True\nTrue\nFalse', 'The passing boundary includes 80. The chained comparison checks both limits. Comparing with 100 is a separate question and does not modify score.'),
    ], 'For 137 minutes, calculate complete 25-minute sessions and remaining minutes. Then check whether a score of 79 meets an inclusive 80-point threshold. Print clear labels for each result.', 'Use // and % with the same divisor. An inclusive boundary uses >=, not >.'),
  unit(5, 'conditions-and-indentation', 'Python Conditions and Indentation',
    'A conditional selects which suite of instructions runs. An if statement evaluates its condition; elif provides another test when earlier tests did not match; else handles the remaining case. In one if/elif/else chain, only the first matching branch runs. Separate if statements are separate decisions and may all run. Choose the structure that expresses the problem.\n\nA colon introduces each branch suite, and consistent indentation groups its statements. Four spaces per level is the conventional style used here. Indentation is syntax, not decoration. A line dedented back to the outer level runs after the decision rather than belonging to the last branch. Avoid mixing tabs and spaces.\n\nThink about boundaries before writing a condition. If 80 passes, test 79, 80 and 81. If grades are ordered from strongest to weakest, place the strongest threshold first; otherwise a high score may satisfy an earlier weaker condition. Validation is a separate concern: an impossible score such as 150 should not silently receive the highest valid grade. These small test cases expose logic defects that a single happy-path example can hide.',
    'Only the first matching branch of one if/elif/else chain executes.', [
      example('Include the passing boundary', 'score = 80\nif score >= 80:\n    print("Pass")\nelse:\n    print("Retry")\nprint("Test finished")', 'Pass\nTest finished', 'The first branch includes the boundary value. The final print is outside both branches, so it runs after the decision regardless of the selected branch.'),
      example('Order thresholds', 'score = 92\nif score >= 90:\n    print("Excellent")\nelif score >= 80:\n    print("Passed")\nelse:\n    print("Keep practising")', 'Excellent', 'A score of 92 also exceeds 80, but the first branch already matched. The interpreter does not execute the elif branch in the same chain.'),
      example('Reject an invalid range', 'score = 105\nif not 0 <= score <= 100:\n    print("Invalid score")\nelif score >= 80:\n    print("Pass")\nelse:\n    print("Retry")', 'Invalid score', 'Range validation happens before grading. A large numeric value is not automatically a valid score. This is an example of checking domain constraints, not just data types.'),
    ], 'Write a decision that rejects scores outside 0 to 100, prints Pass for scores at least 80, and Retry otherwise. Run it with 79, 80, 81 and 105. Explain why validation belongs first.', 'Keep all grading branches in one chain and place the invalid-range condition first.'),
  unit(6, 'loops-and-range', 'Python Loops and Range',
    'A loop repeats instructions according to a defined iteration rule. A for loop visits items from an iterable; range supplies a sequence of integers without building a list of all of them. range(stop) begins at zero and excludes stop. range(start, stop) uses an explicit beginning and still excludes the end. This boundary convention is consistent with slicing.\n\nA while loop repeats while its condition is true. Something inside or outside the loop must eventually change that condition if the program is meant to finish. Update the controlling state deliberately and trace the smallest input before increasing the workload. The browser practice runtime stops unresponsive code, but a timeout is a safety net, not correct loop design.\n\nAn accumulator stores a running result. Initialise it before the loop, then update it on each iteration. Resetting it inside the loop discards earlier work. break exits the nearest loop; continue skips to its next iteration. Use either only when it clarifies the logic. When a loop is wrong, write down the variable values after each iteration instead of changing its start and stop numbers at random.',
    'range excludes its stop value, and a running total must be initialised before iteration.', [
      example('Inspect range boundaries', 'for day in range(1, 4):\n    print(day)', '1\n2\n3', 'The sequence begins at one and stops before four. Three instructions print on three iterations. A for loop gives day a new item value each time.'),
      example('Build a running total', 'total = 0\nfor minutes in range(10, 31, 10):\n    total += minutes\nprint(total)', '60', 'The step is ten, so the loop visits ten, twenty and thirty. The single total initialised before the loop accumulates all three values. The final print is outside the loop.'),
      example('Make a while loop terminate', 'remaining = 3\nwhile remaining > 0:\n    print(remaining)\n    remaining -= 1\nprint("Done")', '3\n2\n1\nDone', 'Each iteration decreases the controlling value. Once it reaches zero the condition is false, and execution moves to the final print. Omitting the update would make this example unbounded.'),
    ], 'Use a for loop to total five daily sessions of 20 minutes. Then write a while countdown from three to one, followed by Done. Explain why the total initialisation and countdown update belong where you placed them.', 'Use range(5) for five iterations. Decrease the while control variable inside its loop.'),
  unit(7, 'lists-and-mutation', 'Python Lists and Mutation',
    'A list stores an ordered collection of references to values. Indexing and slicing use the same zero-based, stop-excluded conventions you studied for strings. Unlike strings, lists are mutable: you can replace an element, append another one or remove an item. Mutation changes the existing list rather than necessarily constructing a new list.\n\nNames can refer to the same mutable object. Assigning alias = scores does not copy every element into an independent collection. A mutation through alias is visible through scores because both names refer to the same list. scores.copy() creates a shallow copy of the outer list. Nested mutable objects can still be shared, so do not describe shallow copying as complete recursive independence.\n\nMethods have different return contracts. append changes the list and returns None; it does not return the updated list. Write scores.append(90), then inspect scores. Assigning scores = scores.append(90) loses the original list binding by replacing it with None. When processing a collection, avoid removing items from the same list while iterating over it unless you have carefully defined the algorithm. A separate result list is usually easier for a beginner to reason about.',
    'Assignment shares the same list reference; a shallow copy creates a separate outer list.', [
      example('Append and replace', 'scores = [70, 80]\nscores.append(90)\nscores[0] = 75\nprint(scores)', '[75, 80, 90]', 'append adds an element at the end. The indexed assignment changes the first existing element. The list keeps its order and now has three elements.'),
      example('Inspect aliasing', 'scores = [70, 80]\nalias = scores\nalias.append(90)\nprint(scores)\nprint(alias is scores)', '[70, 80, 90]\nTrue', 'Both names refer to the same object. The is comparison checks identity here; it does not merely compare the text representation of the lists.'),
      example('Copy the outer list', 'scores = [70, 80]\ncopy = scores.copy()\ncopy.append(90)\nprint(scores)\nprint(copy)', '[70, 80]\n[70, 80, 90]', 'Appending to the separate outer list does not append to the original. These lists contain only integers, so the nested-sharing limitation does not complicate this particular example.'),
    ], 'Create a list of three study durations, copy it, append a fourth duration only to the copy, and print both lists. Then show what changes if you use an alias instead. Do not assign the return value of append back to the list.', 'Print both lists after mutation. Use is to investigate whether two names refer to the same object.'),
  unit(8, 'tuples-and-unpacking', 'Python Tuples and Unpacking',
    'A tuple is an ordered sequence whose element references cannot be replaced after construction. It is useful for a small record whose positions have a stable meaning, such as a label and a duration returned together. A tuple can still contain a mutable object; immutability of the outer tuple does not freeze everything nested inside it.\n\nThe comma is what forms a tuple in a single-value expression. (5) is the integer five in grouping parentheses; (5,) is a one-element tuple. Parentheses make tuple syntax readable, especially inside other expressions. Empty parentheses form the empty tuple.\n\nUnpacking binds several names from an iterable in one assignment. The number of unstarred targets must match the number of values. A starred target can collect remaining values into a list. Choose descriptive target names because positional data otherwise becomes hard to interpret. Unpacking is not limited to tuples, but a tuple provides a clear first example. If a record develops many fields or unclear positions, a named structure may be more appropriate.',
    'Tuple unpacking binds names to sequence items; a single-item tuple needs a comma.', [
      example('Unpack a small record', 'session = ("Python", 30)\nsubject, minutes = session\nprint(subject)\nprint(minutes)', 'Python\n30', 'The first item binds to subject and the second to minutes. Unpacking does not remove items from the original tuple or change its length.'),
      example('Notice the comma', 'single = (5,)\ngrouped = (5)\nprint(type(single).__name__)\nprint(type(grouped).__name__)', 'tuple\nint', 'The trailing comma creates a one-item tuple. Parentheses alone can group an ordinary expression and do not necessarily create a tuple.'),
      example('Collect remaining items', 'first, *remaining = (10, 20, 30)\nprint(first)\nprint(remaining)', '10\n[20, 30]', 'The first target receives one item. The starred target receives a list containing the remaining items, even though the source collection is a tuple.'),
    ], 'Represent one study session as a tuple containing a subject, duration and completed flag. Unpack it into meaningful names and print them. Also create and inspect a one-item tuple without accidentally constructing just a number.', 'Use commas between tuple elements. Match the unpacking target count to the three values.'),
  unit(9, 'dictionaries-and-key-lookup', 'Python Dictionaries and Key Lookup',
    'A dictionary associates keys with values. Use it when a descriptive lookup key expresses the relationship better than a numeric position. A subject-to-duration mapping lets you request the minutes for Python directly without remembering which list index represents Python. Keys must be hashable, and each key occurs at most once in the mapping. Assigning an existing key replaces its associated value.\n\nIndex-style lookup with mapping[key] raises KeyError if the key is missing. get(key, default) provides an explicit fallback. Do not use a fallback that hides a genuine data defect: zero minutes may be a meaningful result rather than a useful substitute for missing configuration. Decide whether absence is acceptable in this part of the program.\n\nDictionary iteration preserves insertion order in modern Python. Looping over a dictionary yields keys; items() gives key-value pairs for unpacking. Membership with in checks keys, not all stored values. Keep these contracts distinct. When displaying results, use a clear order if the domain requires sorting rather than depending accidentally on the order in which input arrived.',
    'Dictionary membership checks keys, and get can supply an explicit missing-key fallback.', [
      example('Read and update a key', 'minutes = {"Python": 30, "HTML": 20}\nminutes["Python"] = 40\nprint(minutes["Python"])\nprint(len(minutes))', '40\n2', 'The assignment updates an existing key rather than adding a third entry. A dictionary contains one associated value for each distinct key.'),
      example('Handle a missing key', 'minutes = {"Python": 30}\nprint(minutes.get("CSS", 0))\nprint("Python" in minutes)\nprint(30 in minutes)', '0\nTrue\nFalse', 'get returns the chosen default for the missing CSS key. Membership checks keys, so the stored numeric value 30 is not itself a matching key.'),
      example('Visit key-value pairs', 'minutes = {"Python": 30, "HTML": 20}\nfor subject, duration in minutes.items():\n    print(subject, duration)', 'Python 30\nHTML 20', 'items provides pairs that the loop unpacks. The output follows the insertion order in this example. The dictionary is not sorted alphabetically automatically.'),
    ], 'Build a subject-to-minutes dictionary for three subjects. Update one duration, print all pairs, and handle an optional fourth subject using an intentional fallback. Explain when bracket lookup would be preferable to get.', 'Use items() for both parts of each entry. Check membership before requiring an optional key.'),
  unit(10, 'sets-and-membership', 'Python Sets and Membership',
    'A set represents distinct hashable values with membership as a central operation. It is useful for questions such as which subjects appear in both a requested and an available collection. It does not provide a positional sequence interface and does not promise an iteration order suitable for a stable display.\n\nConstruct an empty set with set(). Empty braces create an empty dictionary instead. Repeated values collapse into a single set member. That makes a set useful for deduplication when you do not need the original ordering or duplicate count. If either matters, keep the original sequence and choose an algorithm that preserves the information you need.\n\nUnion combines members from either set; intersection keeps common members; difference keeps members from the left that are absent on the right. Those operations return new sets. For reproducible printed examples, sort the result before displaying it. remove raises KeyError for an absent member; discard tolerates its absence. Choosing the latter can be appropriate when absence is expected, but it should not silently hide a broken invariant.',
    'A set stores distinct members, not a promised display order or indexed sequence.', [
      example('Remove duplicates intentionally', 'subjects = {"Python", "HTML", "Python"}\nprint(len(subjects))\nprint("Python" in subjects)', '2\nTrue', 'The repeated Python value does not create another member. The membership test asks whether that value belongs to the set, not where it appears.'),
      example('Compare two collections', 'requested = {"Python", "CSS"}\navailable = {"Python", "HTML"}\nprint(sorted(requested & available))\nprint(sorted(requested - available))', "['Python']\n['CSS']", 'Intersection identifies the available requested subject. Difference identifies what is requested but unavailable. Sorting makes the display deterministic without claiming that the set itself is ordered.'),
      example('Create and update an empty set', 'completed = set()\ncompleted.add("HTML")\ncompleted.add("HTML")\ncompleted.discard("CSS")\nprint(sorted(completed))', "['HTML']", 'Adding the same member again changes nothing. discard permits the absent CSS member. The empty collection is explicitly a set, not an empty dictionary.'),
    ], 'Compare required subjects with completed subjects. Print a sorted list of remaining subjects and a sorted list of completed requirements. Include a duplicate in your source data and explain what information the set retains.', 'remaining = required - completed. Sort only for display, not because set iteration has become ordered.'),
  unit(11, 'functions-and-return-values', 'Python Functions and Return Values',
    'A function gives a reusable operation a name. Its definition describes parameters and a body; calling it supplies arguments and executes that body. Merely defining a function does not run its calculation. Keep the purpose small enough that you can explain the input and output contract in a sentence.\n\nreturn sends a value back to the caller and exits the current function call. print writes a display side effect; it is not a replacement for returning a value that another calculation needs. A function without an explicit returned value returns None. This distinction matters when you want to combine operations instead of displaying everything immediately.\n\nLocal names created during a call are separate from the caller names that supplied values. Avoid relying on unrelated global variables when an argument would make the dependency explicit. Functions are easier to test when the same explicit input produces the same result without changing outside state. Later lessons introduce more parameter rules and scope behaviour, but a clear calculation and return is the best starting point.',
    'return supplies a value to the caller; print only displays a value.', [
      example('Return a calculated result', 'def study_total(days, minutes):\n    return days * minutes\n\nresult = study_total(5, 30)\nprint(result)', '150', 'The function receives two arguments, computes their product and returns it. The caller chooses to print the returned result. No output occurs merely from defining study_total.'),
      example('Recognise an implicit None', 'def show_message():\n    print("Ready")\n\nresult = show_message()\nprint(result)', 'Ready\nNone', 'The function displays Ready but has no explicit return expression. The caller therefore receives None, which the final print makes visible.'),
      example('Compose returned values', 'def double(value):\n    return value * 2\n\nprint(double(10) + double(5))', '30', 'Each call returns a number. The addition combines those numbers before the outer print displays the total. This would not work the same way if double only printed its result.'),
    ], 'Define a function taking daily minutes and number of days, return the total, and call it with two different inputs. Keep printing outside the function. Explain how you would test the return value without inspecting screen output.', 'Write return inside the function. Store or compare the call result before printing it.'),
  unit(12, 'parameters-defaults-and-scope', 'Python Parameters, Defaults and Scope',
    'Parameters name the inputs a function accepts. Positional arguments are matched by position, while keyword arguments identify their parameter names explicitly. A default provides a value when the caller omits that argument. Choose defaults that make sense for the operation rather than using them to hide a required decision.\n\nDefault expressions are evaluated when the function definition executes, not freshly on every call. A mutable default such as items=[] can therefore be shared across calls. Use None as a sentinel and construct a new list inside the function when each omitted argument should mean a fresh collection. Passing an existing list intentionally still permits the function to mutate that list, so document that contract.\n\nAssignments inside a function normally create local bindings. Reading an outer value is different from assigning an outer binding. Prefer returning a new value and assigning it in the caller over reaching for global state. This keeps the source of a change visible and makes the function easier to reuse. A function parameter is a local name bound to the supplied object, not an automatic deep copy of that object.',
    'Use a fresh collection inside the call instead of a mutable default shared between calls.', [
      example('Use a default intentionally', 'def total(days, minutes=30):\n    return days * minutes\n\nprint(total(5))\nprint(total(minutes=20, days=3))', '150\n60', 'The omitted minutes argument receives its default on the first call. Explicit keywords make the second call readable without depending on argument order.'),
      example('Build a fresh optional list', 'def record(value, items=None):\n    if items is None:\n        items = []\n    items.append(value)\n    return items\n\nprint(record("HTML"))\nprint(record("Python"))', "['HTML']\n['Python']", 'Each omitted items argument causes a new list to be constructed inside that call. The second result does not accidentally contain the first call’s subject.'),
      example('Separate local and caller bindings', 'minutes = 30\n\ndef adjust(value):\n    minutes = value + 5\n    return minutes\n\nprint(adjust(10))\nprint(minutes)', '15\n30', 'The assignment in adjust creates a local name. Returning its value does not overwrite the caller’s minutes binding. The caller can explicitly store the result if that is desired.'),
    ], 'Write a function that returns a fresh list of revision tasks when no list is supplied. Call it twice and prove the results do not accumulate unintentionally. Add one optional keyword argument and explain its default.', 'Use items=None, then test items is None inside the function.'),
  unit(13, 'comprehensions', 'Python Comprehensions',
    'A comprehension constructs a collection from an iterable using an expression and optional filtering conditions. Read a simple list comprehension as: evaluate the leading expression for each item that passes the filter. It is a compact collection-building tool, not a requirement to replace every loop.\n\nThe expression determines what enters the result; the filter determines whether an input participates. These roles are separate. An if after the iterable filters items, while a conditional expression before for chooses between output values. Start with a normal loop if the distinction is not yet clear. Name the source collection and result so the transformation can be explained.\n\nList, set and dictionary comprehensions build different collection types. A dictionary comprehension creates key-value associations, and duplicate keys overwrite earlier values just as in other dictionary construction. Avoid side effects inside a comprehension. If the code is mainly printing, updating unrelated state or handling several branches, an explicit loop usually communicates the intent better. Compact syntax is useful only when the reader can still reason about the operation.',
    'The comprehension expression transforms each included item; its trailing condition filters inputs.', [
      example('Transform each input', 'minutes = [10, 20, 30]\ndoubled = [value * 2 for value in minutes]\nprint(doubled)\nprint(minutes)', '[20, 40, 60]\n[10, 20, 30]', 'The expression multiplies each number before it enters the new list. The original list is not changed by this construction.'),
      example('Filter before collecting', 'scores = [65, 80, 92]\npassed = [score for score in scores if score >= 80]\nprint(passed)', '[80, 92]', 'Only values satisfying the inclusive passing condition enter the result. The leading expression is score, so the included numeric values are retained without another transformation.'),
      example('Build named associations', 'subjects = ["HTML", "Python"]\nlengths = {subject: len(subject) for subject in subjects}\nprint(lengths["HTML"])\nprint(lengths["Python"])', '4\n6', 'The comprehension produces a dictionary, not a list. Each subject becomes a key associated with its character count, and the prints perform explicit key lookups.'),
    ], 'From durations [10, 25, 40, 15], build a new list containing double the durations that are at least 20. Then write the equivalent ordinary loop and compare the results.', 'Transform with value * 2 and filter with value >= 20. Do not reverse those roles.'),
  unit(14, 'exceptions-and-recovery', 'Python Exceptions and Recovery',
    'An exception signals that an operation could not complete normally. It interrupts the current path until an appropriate handler is found. A syntax error in your program and a ValueError while parsing external text are different problems; do not treat every failure as something to ignore and continue past.\n\nA try suite contains the operation that may fail. An except clause handles a specified exception class. Keep the protected operation small enough that the handler’s meaning stays clear. Catching Exception around the whole program can conceal unrelated bugs, such as a misspelled name in the recovery logic. Catch the failures that the program can actually recover from.\n\nThe else suite runs if the try suite completes without an exception. finally runs as execution leaves the try statement, whether the operation succeeded or failed. It is useful for cleanup, but a context manager is often clearer for resource management. A recovery value must make sense in the domain: returning zero for invalid exam data can silently convert a bad record into an apparently valid score. Prefer an explicit invalid result when that distinction matters.',
    'Catch a specific expected failure and make recovery explicit rather than hiding unrelated errors.', [
      example('Handle invalid integer text', 'text = "twelve"\ntry:\n    value = int(text)\nexcept ValueError:\n    print("Enter integer digits")', 'Enter integer digits', 'int cannot parse this word as an integer, so ValueError selects the handler. The program displays an actionable message instead of pretending conversion succeeded.'),
      example('Separate success and cleanup', 'try:\n    value = int("12")\nexcept ValueError:\n    print("Invalid")\nelse:\n    print(value * 2)\nfinally:\n    print("Checked")', '24\nChecked', 'Conversion succeeds, so else runs. finally then runs on exit from the statement. No Invalid message is printed because the except branch was not selected.'),
      example('Raise a domain error', 'def checked_minutes(value):\n    if value < 0:\n        raise ValueError("Minutes cannot be negative")\n    return value\n\ntry:\n    checked_minutes(-5)\nexcept ValueError as error:\n    print(str(error))', 'Minutes cannot be negative', 'The value is numeric but invalid for the application’s domain. Raising an explicit error distinguishes this situation from a successful duration calculation.'),
    ], 'Write a parser for a positive number of study minutes. Handle nonnumeric text and reject negative values. Test valid text, an invalid word and a negative number without catching every possible exception.', 'Keep int conversion and domain validation visible. Catch ValueError only where recovery is intended.'),
  unit(15, 'modules-and-imports', 'Python Modules and Imports',
    'A module provides a namespace that groups related definitions. Importing a module binds a name through which you can access its members. Using math.isqrt makes both the operation and its source visible; importing one selected name can be convenient when that name remains unambiguous in the surrounding code.\n\nThe standard library ships with Python, but availability still depends on the execution environment. Browser practice is not an unrestricted operating-system shell. Do not assume that every standard-library feature can access files, spawn processes or contact networks here. Third-party packages are not automatically available just because an example on the internet imports them.\n\nAvoid wildcard imports in introductory application code because they hide where names came from and can overwrite existing bindings. Do not name your own source file math.py or json.py when you intend to import the standard-library module of that name: local naming conflicts can produce confusing behaviour. Imports can execute module-level code, so shared modules should avoid unexpected work at import time. A main guard lets a module distinguish direct execution from being imported by another program.',
    'Importing a module provides a namespace; it does not make every external package or system capability available.', [
      example('Use a module namespace', 'import math\nprint(math.isqrt(81))\nprint(math.ceil(2.2))', '9\n3', 'isqrt gives the integer square root, and ceil rounds upward to an integer. Prefixing both names with math makes their origin explicit.'),
      example('Import one selected name', 'from math import gcd\nprint(gcd(18, 24))', '6', 'gcd becomes a name in the current namespace. This is not the same spelling as importing math and then calling math.gcd, although both access the same standard-library operation.'),
      example('Inspect a familiar namespace', 'import string\nprint(string.ascii_lowercase[:3])\nprint(string.digits)', 'abc\n0123456789', 'The module also exposes useful constant values, not only functions. The slice uses the same stop-excluded rule already studied for strings.'),
    ], 'Use math.isqrt on three perfect squares and math.gcd on two positive integers. Keep module-qualified names in one version, then demonstrate a selected-name import in another. Explain the naming trade-off.', 'Use only the standard-library operations shown. No package installation or network access is needed.'),
  unit(16, 'standard-library-tools', 'Practical Python Standard-Library Tools',
    'The standard library contains focused tools that prevent unnecessary reinvention. Choose a tool by its input and output contract rather than importing a large collection of names and guessing which one might work. statistics.mean computes an arithmetic mean; collections.Counter counts occurrences; itertools can build controlled iteration patterns. Each solves a different problem.\n\nA count is not the same statistic as an average. If duplicate subjects are meaningful events, converting to a set before counting destroys useful frequency information. Likewise, an average can hide variation: two students with very different scores may have the same mean as a consistent student. Report a measure only when it answers the question you are asking.\n\nInspect edge cases before relying on an operation. An empty data collection may require an explicit decision instead of a default that looks like a valid measurement. Iterators can also be consumed; converting a tiny iterator to a list is useful for inspection, but building enormous collections defeats their purpose. These examples are deliberately bounded and deterministic, requiring no external packages or network services.',
    'Choose a standard-library tool according to its input/output contract and preserve meaningful data.', [
      example('Calculate an arithmetic mean', 'from statistics import mean\nminutes = [20, 30, 40]\nprint(mean(minutes))', '30', 'The sum of the three durations is ninety and the item count is three. mean computes their arithmetic average. This does not imply that each session lasted thirty minutes.'),
      example('Count repeated values', 'from collections import Counter\ncounts = Counter(["Python", "HTML", "Python"])\nprint(counts["Python"])\nprint(counts["CSS"])', '2\n0', 'Counter retains frequency rather than discarding repeats. Its missing-member count is zero, a deliberate contract that differs from ordinary dictionary bracket lookup.'),
      example('Pair consecutive values', 'from itertools import pairwise\nfor previous, current in pairwise([10, 15, 25]):\n    print(current - previous)', '5\n10', 'pairwise yields adjacent pairs. The loop calculates successive changes without treating the first item as a change from an invented zero. It requires Python 3.10 or newer, supported by this course runtime.'),
    ], 'For durations [20, 30, 20, 40], calculate the mean and count how often 20 occurs. Explain why using a set first would change the meaning of the average and lose frequency information.', 'Pass the original duration list to both tools. Choose mean and Counter for their different purposes.'),
  unit(17, 'json-and-bounded-files', 'Python JSON and Bounded File Handling',
    'JSON is a text data format, not executable Python source. json.loads parses JSON text into Python values; json.dumps serialises compatible values into JSON text. JSON true, false and null map to Python True, False and None. Object keys are text, and JSON does not preserve arbitrary Python object types.\n\nParsing is not complete validation. A syntactically valid JSON document can still have missing fields, unexpected types or unreasonable sizes. Check the shape and domain constraints before treating data as a trusted record. Never use eval to parse text received from a user or a remote system. The JSON parser is built for this job and does not need to execute source code.\n\nFile access also has an environment boundary. The practice interpreter uses an isolated virtual filesystem and does not promise persistence after a session or reload. To demonstrate the file interface without changing any real files, these examples use io.StringIO. Its with statement shows a context-managed text stream that is closed afterward. A production program using real paths would additionally need explicit encoding, path boundaries, size limits and an appropriate storage lifecycle.',
    'JSON parsing constructs data, not executable source, and parsed records still need validation.', [
      example('Read JSON data', 'import json\nrecord = json.loads(\'{"subject":"Python","minutes":30,"done":true}\')\nprint(record["subject"])\nprint(record["done"])', 'Python\nTrue', 'The JSON boolean becomes a Python bool. The parsed dictionary can be queried with normal key access, but a real application should still verify required keys and value types.'),
      example('Serialise predictably', 'import json\nrecord = {"minutes": 30, "done": False}\nprint(json.dumps(record, sort_keys=True))', '{"done": false, "minutes": 30}', 'dumps creates a JSON string. Sorting keys makes this example’s output stable; it does not change the dictionary’s meaning or add validation.'),
      example('Read a bounded text stream', 'from io import StringIO\nwith StringIO("Python\\nHTML\\n") as stream:\n    first = stream.readline().strip()\n    second = stream.readline().strip()\n    print(first)\n    print(second)\nprint(stream.closed)', 'Python\nHTML\nTrue', 'The stream contains fixed in-memory text, not a persistent external file. readline reads one line at a time, and leaving the context closes the stream.'),
    ], 'Parse a small JSON revision record and check that minutes is an integer in a reasonable positive range. Serialise an updated record without executing any input as Python. Explain why the browser does not provide durable file storage here.', 'Use json.loads and explicit isinstance/range checks. Keep any text-stream demonstration in StringIO.'),
  unit(18, 'classes-and-instances', 'Python Classes and Instances',
    'A class defines a type whose instances can hold related state and behaviour. Use it when the relationship between the data and operations becomes clearer, not merely because classes look more advanced. A small dictionary and a function can be the better design for a simple one-off calculation.\n\n__init__ initialises an instance after it is created. The conventional first parameter self refers to the instance receiving the method call. Assigning self.name creates or updates an attribute on that instance. By contrast, a mutable attribute created directly in the class body can be shared across instances, which is often an unwanted surprise for beginners.\n\nA method call such as session.finish() passes the instance to its method automatically. Keep the method’s state change understandable and protect domain constraints where needed. Public attributes are not automatically validated simply because they belong to a class. The examples focus on separate instance state and a clear method contract; inheritance is not required to organise this small model.',
    'Instance attributes assigned through self belong to that instance rather than an implicitly shared mutable class collection.', [
      example('Create an instance', 'class Session:\n    def __init__(self, subject, minutes):\n        self.subject = subject\n        self.minutes = minutes\n\nsession = Session("Python", 30)\nprint(session.subject)\nprint(session.minutes)', 'Python\n30', 'The constructor arguments initialise two attributes on the new instance. The class defines the structure; the session name refers to one concrete instance.'),
      example('Keep per-instance state separate', 'class Checklist:\n    def __init__(self):\n        self.items = []\n\nfirst = Checklist()\nsecond = Checklist()\nfirst.items.append("Read")\nprint(first.items)\nprint(second.items)', "['Read']\n[]", 'A fresh list is created in each initialisation. Appending to the first instance’s items does not append to the second instance’s separate list.'),
      example('Call a state-changing method', 'class Session:\n    def __init__(self):\n        self.completed = False\n\n    def finish(self):\n        self.completed = True\n\nsession = Session()\nprint(session.completed)\nsession.finish()\nprint(session.completed)', 'False\nTrue', 'finish receives the instance and changes its completed attribute. The call, not the mere method definition, performs the change.'),
    ], 'Create a StudySession class with subject, minutes and completed instance attributes. Add a finish method. Create two instances, finish only one, and demonstrate that their completion states remain independent.', 'Initialise mutable state inside __init__. Access the current instance with self.'),
  unit(19, 'tests-and-debugging', 'Python Tests and Debugging',
    'A test compares observed behaviour with an explicit expectation. It is stronger than glancing at output and deciding it looks plausible. Start with a small function whose return contract is clear, then cover a normal case, a boundary and a failure case. A passing example proves that particular check, not every possible property of the program.\n\nAssertions are convenient for small learning checks, but ordinary assert statements can be disabled when Python runs with optimisation. Do not use assert as the only protection for user input, authentication or another required production invariant. Explicit validation should raise or return an intentional failure independently of optimisation settings. unittest supplies test-case methods for a structured suite.\n\nDebugging begins with reproducing the defect. Reduce the input, locate the first point where observed state differs from the prediction, and fix the cause rather than editing the expected output until the test turns green. Keep a regression check that would have failed before the fix. A test that never calls the relevant function, or only repeats its implementation in a different spelling, can create false confidence.',
    'Test normal cases, boundaries and expected failures; a passing test does not prove all possible behaviour.', [
      example('Check an exact return value', 'def total(days, minutes):\n    return days * minutes\n\nassert total(5, 30) == 150\nassert total(0, 30) == 0\nprint("Two checks passed")', 'Two checks passed', 'The second assertion tests the zero-day boundary. The message is printed only after both assertions succeed in this normal interpreter configuration.'),
      example('Check a required failure', 'def checked_minutes(value):\n    if value < 0:\n        raise ValueError("Negative duration")\n    return value\n\ntry:\n    checked_minutes(-1)\nexcept ValueError:\n    print("Expected rejection")\nelse:\n    raise RuntimeError("Missing rejection")', 'Expected rejection', 'The else branch would fail the check if the invalid input were accepted. Merely catching an exception without an explicit no-exception failure would not prove the rejection happened.'),
      example('Use a structured test case', 'import unittest\n\nclass TotalChecks(unittest.TestCase):\n    def test_product(self):\n        self.assertEqual(5 * 30, 150)\n\nresult = unittest.TestResult()\nTotalChecks("test_product").run(result)\nprint(result.testsRun)\nprint(result.wasSuccessful())', '1\nTrue', 'The test case executes one named test and records its result without printing an environment-dependent runner banner. A real application would test its actual function rather than only this introductory arithmetic expression.'),
    ], 'Write a study-total function and checks for ordinary input, zero days and a negative-duration rejection. Deliberately introduce an off-by-one error, observe which check catches it, then fix the implementation without changing the valid expectation.', 'Choose expectations from the problem statement. Ensure the expected-failure check also fails when no exception is raised.'),
  unit(20, 'revision-planner-project', 'Python Project: Build a Revision Planner',
    'This project combines the core tools into a small revision planner without introducing a paid service or a web framework. Its input is a bounded list of session records; its output is a readable summary of planned and completed minutes. Keep collection processing separate from display so that calculations can be tested independently.\n\nEach record needs a subject, nonnegative integer minutes and a completed boolean. Define those requirements before writing the loop. Reject bad records explicitly instead of silently converting them into zero-minute sessions. A bool is a subclass of int in Python, so type(value) is int is a useful exact-type check when True must not count as one minute. This detail illustrates why validation rules should express the domain precisely.\n\nStart with hard-coded sample data and pure functions. Add JSON import/export only after the calculations and validation pass checks. In browser practice, this means parsing and printing JSON text, not promising durable file storage. A graphical interface, database and network synchronisation are separate future projects. A clear, well-tested console tool is a complete result for this scope.\n\nWork in small checkpoints: validate one record, total two records, calculate completed minutes, then format the report. Verify empty input, all incomplete sessions, all complete sessions and one invalid duration. Keep the first project small enough that you can explain every line without relying on unexplained libraries.',
    'Validate session records and keep pure calculations separate from report formatting.', [
      example('Total the planned minutes', 'sessions = [\n    {"subject": "Python", "minutes": 30, "done": True},\n    {"subject": "HTML", "minutes": 20, "done": False},\n]\nplanned = sum(session["minutes"] for session in sessions)\nprint(planned)', '50', 'The generator expression supplies each duration to sum. The result is planned time, not completed time: completion status has not been used as a filter.'),
      example('Count completed minutes', 'sessions = [\n    {"minutes": 30, "done": True},\n    {"minutes": 20, "done": False},\n]\ncompleted = sum(session["minutes"] for session in sessions if session["done"])\nprint(completed)', '30', 'The condition includes only completed sessions. This is a minutes total, not merely the number of completed records. Keep those measures separate in the final report.'),
      example('Validate and report through a function', 'def report(sessions):\n    for session in sessions:\n        value = session["minutes"]\n        if type(value) is not int or value < 0:\n            raise ValueError("Invalid duration")\n    planned = sum(item["minutes"] for item in sessions)\n    return "Planned minutes: " + str(planned)\n\nprint(report([{"minutes": 30}, {"minutes": 20}]))\nprint(report([]))', 'Planned minutes: 50\nPlanned minutes: 0', 'This small checkpoint validates duration values and formats a total. The complete assignment additionally validates subject and done fields. The empty list produces a meaningful zero total rather than an invented session.'),
    ], 'Build a revision planner with validate_session, planned_minutes, completed_minutes and format_report functions. Validate nonempty subject strings, exact nonnegative integer minutes and boolean done fields. Demonstrate empty input, mixed completion states and invalid records. Add JSON text import/export and at least six checks. Do not require a network, real file persistence, a database or third-party packages.', 'Build and test the pure calculations first. Validate required keys before lookup, and keep JSON parsing separate from record validation.'),
];
